function extractBalancedSegment(s, opener, closer, startIdx) {
  let i = startIdx, depth = 0, inStr = false, esc = false;
  for (; i < s.length; i++) if (s[i] === opener) { depth = 1; i++; break; }
  if (depth === 0) return null;
  for (; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') inStr = false;
      continue;
    } else {
      if (c === '"') { inStr = true; continue; }
      if (c === opener) { depth++; continue; }
      if (c === closer) { depth--; if (depth === 0) return s.slice(startIdx, i + 1); continue; }
    }
  }
  return null;
}

