  if (iObj >= 0 && (iArr < 0 || iObj < iArr)) seg = extractBalancedSegment(cleaned, '{', '}', iObj);
  else if (iArr >= 0) seg = extractBalancedSegment(cleaned, '[', ']', iArr);
