function robustParse(str) {
  if (typeof str !== 'string') return null;

  let clean = str.trim();
  clean = clean.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();

  try { return JSON.parse(clean); } catch (e) {}

  const matchBlock = clean.match(/(\{[\s\S]*\})/);
  if (matchBlock) {
    try { return JSON.parse(matchBlock[1]); } catch(e) {}
  }

  const fallbackObj = {};

  const protocolMatch = clean.match(/"protocol_text"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (protocolMatch) fallbackObj.protocol_text = unescapeJsonString(protocolMatch[1]);

  const planMatch = clean.match(/"implementation_plan"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (planMatch) fallbackObj.implementation_plan = unescapeJsonString(planMatch[1]);

  const templateMatch = clean.match(/"validation_report_template"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (templateMatch) fallbackObj.validation_report_template = unescapeJsonString(templateMatch[1]);

  const stateMatch = clean.match(/"state"\s*:\s*(\{[\s\S]*?\})\s*(?:,|})/); 
  if (stateMatch) {
      try { fallbackObj.state = JSON.parse(stateMatch[1]); } catch(e) {}
  }

  if (Object.keys(fallbackObj).length > 0) return fallbackObj;

  return null;
}

function unescapeJsonString(str) {
  return str
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
    .replace(/\\t/g, '\t');
}

function findPayload(obj, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 3) return null;

  if (obj.protocol_text) return obj;

  const candidates = ['output', 'json', 'data', 'text', 'message', 'content', 'response'];
  for (const key of candidates) {
    if (obj[key]) {
      if (typeof obj[key] === 'string') {
        const parsed = robustParse(obj[key]);
        if (parsed) return parsed;
      } else if (typeof obj[key] === 'object') {
        const found = findPayload(obj[key], depth + 1);
        if (found) return found;
      }
    }
  }
  return null;
}

for (const item of items) {
  let finalObj = null;

  try {
    finalObj = findPayload(item.json);

    if (!finalObj && typeof item.json === 'string') {
        finalObj = robustParse(item.json);
    }
  } catch (err) {}

  const safeOutput = {
    protocol_text: (finalObj?.protocol_text || "").toString(),

